1	<script>
2	import PrimaryButton from "@/components/PrimaryButton";
3	
4	export default {
5	  name: "HeaderTickspeedRowClassic",
6	  components: {
7	    PrimaryButton,
8	  },
9	  props: {
10	    inHeader: {
11	      type: Boolean,
12	      required: false,
13	      default: true,
14	    }
15	  },
16	  data() {
17	    return {
18	      purchasedTickspeed: 0,
19	      freeTickspeed: 0,
20	      isVisible: false,
21	      mult: new Decimal(0),
22	      cost: new Decimal(0),
23	      isAffordable: false,
24	      tickspeed: new Decimal(0),
25	      galaxyCount: 0,
26	      isContinuumActive: false,
27	      continuumValue: 0,
28	      hasTutorial: false,
29	    };
30	  },
31	  computed: {
32	    classObject() {
33	      return {
34	        "c-game-header__tickspeed-row": true,
35	        "c-game-header__tickspeed-row--hidden": !this.isVisible,
36	        "l-inline-padding": !this.inHeader
37	      };
38	    },
39	    multiplierDisplay() {
40	      if (InfinityChallenge(3).isRunning) return `Multiply all Antimatter Dimensions by
41	        ${formatX(1.05 + this.galaxyCount * 0.005, 3, 3)}`;
42	      const tickmult = this.mult;
43	      return `${formatX(tickmult.reciprocal(), 2, 3)} faster / upgrade`;
44	    },
45	    tickspeedDisplay() {
46	      return `Tickspeed: ${format(this.tickspeed, 2, 3)} / sec`;
47	    },
48	    continuumString() {
49	      return formatFloat(this.continuumValue, 2);
50	    },
51	    upgradeCount() {
52	      const purchased = this.purchasedTickspeed;
53	      if (!this.freeTickspeed) return `${formatInt(purchased)} Purchased`;
54	      if (purchased === 0 || this.isContinuumActive) return `${formatInt(this.freeTickspeed)} Free Upgrades`;
55	      return `${formatInt(purchased)} Purchased + ${formatInt(this.freeTickspeed)} Free`;
56	    }
57	  },
58	  methods: {
59	    update() {
60	      this.purchasedTickspeed = player.totalTickBought;
61	      this.freeTickspeed = FreeTickspeed.amount;
62	      const isEC9Running = EternityChallenge(9).isRunning;
63	      this.isVisible = Tickspeed.isUnlocked || isEC9Running;
64	      if (!this.isVisible) return;
65	      this.mult.copyFrom(Tickspeed.multiplier);
66	      this.cost.copyFrom(Tickspeed.cost);
67	      this.isAffordable = !isEC9Running && canAfford(Tickspeed.cost);
68	      this.tickspeed.copyFrom(Tickspeed.perSecond);
69	      this.galaxyCount = player.galaxies;
70	      this.isContinuumActive = Laitela.continuumActive;
71	      if (this.isContinuumActive) this.continuumValue = Tickspeed.continuumValue;
72	      this.hasTutorial = Tutorial.isActive(TUTORIAL_STATE.TICKSPEED);
73	    },
74	    buttonClass() {
75	      return {
76	        "l-long-button": !this.inHeader,
77	        "o-primary-btn--tickspeed": true,
78	        "o-continuum": this.isContinuumActive,
79	        "tutorial--glow": this.isAffordable && this.hasTutorial
80	      };
81	    },
82	    buyUpgrade() {
83	      if (!buyTickSpeed()) return;
84	      Tutorial.turnOffEffect(TUTORIAL_STATE.TICKSPEED);
85	    },
86	  },
87	};
88	</script>
89	
90	<template>
91	  <div :class="classObject">
92	    <div v-if="inHeader">
93	      {{ multiplierDisplay }}
94	    </div>
95	    <div>
96	      <PrimaryButton
97	        v-tooltip="upgradeCount"
98	        :enabled="isAffordable || isContinuumActive"
99	        :class="buttonClass()"
100	        @click="buyUpgrade"
101	      >
102	        <span v-if="!inHeader">Tickspeed </span>
103	        <span v-if="isContinuumActive">Continuum: {{ continuumString }}</span>
104	        <span v-else>Cost: {{ format(cost) }}</span>
105	        <div
106	          v-if="hasTutorial"
107	          class="fas fa-circle-exclamation l-notification-icon"
108	        />
109	      </PrimaryButton>
110	      <PrimaryButton
111	        v-if="!isContinuumActive"
112	        :enabled="isAffordable"
113	        class="o-primary-btn--buy-max"
114	        onclick="buyMaxTickSpeed()"
115	      >
116	        Buy Max
117	      </PrimaryButton>
118	    </div>
119	    <div>
120	      {{ tickspeedDisplay }} <span v-if="!inHeader">({{ multiplierDisplay }})</span>
121	    </div>
122	  </div>
123	</template>
124	
125	<style scoped>
126	.o-primary-btn--tickspeed {
127	  width: 17rem;
128	  position: relative;
129	  font-size: 1.2rem;
130	  margin-right: 0.4rem;
131	  transition: width 0s;
132	}
133	
134	.o-continuum {
135	  transition: width 0s;
136	  cursor: auto;
137	}
138	
139	.l-inline-padding {
140	  padding-top: 1rem;
141	}
142	
143	.l-long-button {
144	  width: 30rem;
145	}
146	</style>
147

