1	<script>
2	import ArmageddonButton from "../../tabs/celestial-pelle/ArmageddonButton";
3	import RealityCurrencyHeader from "../../RealityCurrencyHeader";
4	
5	import HeaderTickspeedRowClassic from "../HeaderTickspeedRowClassic";
6	import HeaderTickspeedRowModern from "../HeaderTickspeedRowModern";
7	
8	import RealityButton from "./RealityButton";
9	
10	// This component contains antimatter and antimatter rate at the start of the game, as well as some additional
11	// information depending on the UI (tickspeed for Classic, game speed for Modern). Everything but antimatter is
12	// removed once Reality is unlocked, to make room for the reality button
13	export default {
14	  name: "HeaderCenterContainer",
15	  components: {
16	    HeaderTickspeedRowClassic,
17	    HeaderTickspeedRowModern,
18	    RealityCurrencyHeader,
19	    RealityButton,
20	    ArmageddonButton,
21	  },
22	  data() {
23	    return {
24	      isModern: false,
25	      hasRealityButton: false,
26	      isDoomed: false,
27	      antimatter: new Decimal(0),
28	      antimatterPerSec: new Decimal(0),
29	    };
30	  },
31	  methods: {
32	    update() {
33	      this.isModern = player.options.newUI;
34	      this.isDoomed = Pelle.isDoomed;
35	      this.antimatter.copyFrom(Currency.antimatter);
36	      this.hasRealityButton = PlayerProgress.realityUnlocked() || TimeStudy.reality.isBought;
37	      if (!this.hasRealityButton) this.antimatterPerSec.copyFrom(Currency.antimatter.productionPerSecond);
38	    },
39	  },
40	};
41	</script>
42	
43	<template>
44	  <div class="c-prestige-button-container">
45	    <span>You have <span class="c-game-header__antimatter">{{ format(antimatter, 2, 1) }}</span> antimatter.</span>
46	    <div
47	      v-if="hasRealityButton"
48	      class="c-reality-container"
49	    >
50	      <RealityCurrencyHeader />
51	      <ArmageddonButton
52	        v-if="isDoomed"
53	        :is-header="true"
54	      />
55	      <RealityButton v-else />
56	    </div>
57	    <div v-else>
58	      You are getting {{ format(antimatterPerSec, 2) }} antimatter per second.
59	      <br>
60	      <HeaderTickspeedRowModern v-if="isModern" />
61	      <HeaderTickspeedRowClassic v-else />
62	    </div>
63	  </div>
64	</template>
65	
66	<style scoped>
67	.c-reality-container {
68	  display: flex;
69	  flex-direction: column;
70	  justify-content: space-between;
71	  align-items: center;
72	}
